const T=(key,vars={})=>{let value=(D[I18N.lang]||D.en)[key]??D.en[key]??key;for(const [name,replacement] of Object.entries(vars))value=value.replaceAll(`{${name}}`,String(replacement));return value};
// All localized fallback messages must describe the live gate, not an old release state.
