async function disputeReasonHash(value){const text=value.trim();if(!text||validHash(text))return text;const digest=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(text));return "0x"+[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,"0")).join("")}
