const REVIEW_SELECTORS=new Set(["0xece1de44","0x98acff0f"]);
const abiWord=(data,index)=>data.slice(10+index*64,10+(index+1)*64).toLowerCase();
const wordUint=(data,index)=>BigInt("0x"+abiWord(data,index));
const wordAddress=(data,index)=>"0x"+abiWord(data,index).slice(24);
const normHash=value=>String(value||"").toLowerCase().replace(/^0x/,"").padStart(64,"0");
function abiString(data,offsetWord){const start=10+Number(wordUint(data,offsetWord))*2,length=Number(BigInt("0x"+data.slice(start,start+64)));const hex=data.slice(start+64,start+64+length*2);return new TextDecoder().decode(Uint8Array.from(hex.match(/../g)||[],x=>parseInt(x,16)))}
function validatePreparedTransaction(tx,from){
  const fail=()=>{throw Error("Prepared transaction failed local safety checks.")};
  if(!tx||!same(tx.from,from)||String(tx.chainId||"").toLowerCase()!==CHAIN||BigInt(tx.value||"0x0")!==0n||!/^0x[0-9a-fA-F]+$/.test(tx.data||""))fail();
  const target=String(tx.to||"").toLowerCase(),selector=tx.data.slice(0,10).toLowerCase();
  if(same(target,USDC)){
    if(selector!=="0x095ea7b3"||tx.data.length!==138||!cfg?.escrow)fail();
    const spender="0x"+tx.data.slice(34,74);
    const expected=pending?.after==="approval"?draft?.buyer_total_units:pending?.after==="bond"?current?.seller_bond_units:null;
    if(!same(spender,cfg.escrow)||expected==null||BigInt("0x"+tx.data.slice(74))!==BigInt(expected))fail();
    return true;
  }
  if(cfg?.escrow&&same(target,cfg.escrow)&&ESCROW_SELECTORS.has(selector)){
    if(selector===PROPOSE_SELECTOR){
      const intent=draft?._intent;if(!intent||tx.data.length!==778)fail();
      const expected=[intent.salt,intent.seller,intent.mode==="automatic"?0:1,draft.amount_units,draft.buyer_reserve_units,intent.fallback_seller_bps,draft.manifest_hash,draft.policy_hash,intent.acceptance_window,intent.delivery_window,intent.decision_window,intent.arbitration_window];
      if(normHash(expected[0])!==abiWord(tx.data,0)||!same(wordAddress(tx.data,1),expected[1])||wordUint(tx.data,2)!==BigInt(expected[2])||wordUint(tx.data,3)!==BigInt(expected[3])||wordUint(tx.data,4)!==BigInt(expected[4])||wordUint(tx.data,5)!==BigInt(expected[5])||normHash(expected[6])!==abiWord(tx.data,6)||normHash(expected[7])!==abiWord(tx.data,7)||wordUint(tx.data,8)!==BigInt(expected[8])||wordUint(tx.data,9)!==BigInt(expected[9])||wordUint(tx.data,10)!==BigInt(expected[10])||wordUint(tx.data,11)!==BigInt(expected[11]))fail();
      return true;
    }
    if(!current||normHash(current.deal_id)!==abiWord(tx.data,0))fail();
    if(selector==="0x2c85de56"&&(normHash($("contentHash").value.trim())!==abiWord(tx.data,1)||abiString(tx.data,2)!==$("uri").value.trim()))fail();
    if(selector==="0x3296497e"&&(normHash(pending?.reason_hash)!==abiWord(tx.data,1)||abiString(tx.data,2)!==$("evidenceUri").value.trim()))fail();
    return true;
  }
  if(cfg?.review_arbitrator&&same(target,cfg.review_arbitrator)&&REVIEW_SELECTORS.has(selector)){
    if(!current||normHash(current.deal_id)!==abiWord(tx.data,0))fail();
    return true;
  }
  fail();
}

async function api(path,body){const r=await fetch("/mainnet"+path,{method:body?"POST":"GET",headers:body?{"Content-Type":"application/json"}:{},body:body?JSON.stringify(body):undefined,cache:"no-store"});const d=await r.json();if(!r.ok)throw Error(d.detail||T("requestFailed"));return d}
function provider(){if(!window.ethereum)throw Error(T("metamaskMissing"));return window.ethereum}
async function wallet(){const p=provider(),a=await p.request({method:"eth_accounts"});if(!a[0])throw Error(T("connectFirst"));if(await p.request({method:"eth_chainId"})!==CHAIN)throw Error(T("switchNetwork"));return a[0]}
function error(e){const m=e?.message||String(e);if(e?.code===4001)return T("cancelled");if(/funds|gas/i.test(m))return T("noGas");if(/allowance|approve/i.test(m))return T("approveFirst");return backendMessage(m)}
function mark(id,text,ok=false){show(id,text);$(id).classList.toggle("ok",ok);$(id).classList.toggle("bad",!ok)}

async function refresh(){cfg=await api("/config"+(account?"?wallet="+account:""));const status=$("status");status.classList.remove("checking","open","closed");status.classList.add(cfg.accepting_funds?"open":"closed");show("status",cfg.accepting_funds?T("accessActive"):T("depositsClosed"));mark("access",cfg.approved_buyer===true?T("approved"):cfg.accepting_funds?T("accessActive"):T("openingSoon"),cfg.approved_buyer===true);$("prepare").disabled=!cfg.accepting_funds}
async function balances(){if(!account)return;const p=provider();const [eth,bal]=await Promise.all([p.request({method:"eth_getBalance",params:[account,"latest"]}),p.request({method:"eth_call",params:[{to:USDC,data:"0x70a08231"+account.slice(2).padStart(64,"0")},"latest"]})]);mark("eth",BigInt(eth)>0n?T("available"):T("noEth"),BigInt(eth)>0n);mark("usdc",format(bal)+" USDC",BigInt(bal)>0n)}
async function connect(){const p=provider();await p.request({method:"eth_requestAccounts"});try{await p.request({method:"wallet_switchEthereumChain",params:[{chainId:CHAIN}]})}catch(e){if(e.code!==4902)throw e;await p.request({method:"wallet_addEthereumChain",params:[{chainId:CHAIN,chainName:"Arbitrum One",nativeCurrency:{name:"Ether",symbol:"ETH",decimals:18},rpcUrls:["https://arb1.arbitrum.io/rpc"],blockExplorerUrls:["https://arbiscan.io"]}]})}account=await wallet();mark("wallet",short(account),true);mark("network","Arbitrum One",true);await refresh();await balances();await reconcileApproval()}
function select(role){["buyerRole","sellerRole"].forEach(id=>$(id).classList.toggle("selected",id===role));visible("create",role==="buyerRole");visible("open",role!=="buyerRole")}
function updateFallback(){const amount=Math.max(0,Number($("amount").value)||0),share=Math.min(100,Math.max(0,Number($("fallback").value)||0)),sellerPrincipal=amount*share/100,buyerPrincipal=amount-sellerPrincipal,review=$("mode").value==="buyer_review",reserve=review?Math.min(100,Math.max(5,amount*.05)):0,sellerTotal=sellerPrincipal+reserve,buyerTotal=buyerPrincipal+reserve;show("fallbackExample",fallbackText(review,amount.toFixed(2),share.toFixed(0),sellerPrincipal.toFixed(2),buyerPrincipal.toFixed(2),reserve.toFixed(2),sellerTotal.toFixed(2),buyerTotal.toFixed(2)))}
function validateSeller(){const value=$("seller").value.trim(),sameWallet=account&&same(value,account);show("sellerError",sameWallet?T("differentWallets"):"");visible("sellerError",sameWallet);return !sameWallet}
function fundingProgress(approved=false,funded=false){const a=$("approvalStep"),f=$("fundingStep");a.className="fund-step "+(approved?"done":"active");f.className="fund-step "+(funded?"done":approved?"active":"");a.querySelector("span").textContent=approved?T("confirmedNetwork"):T("walletWaiting");f.querySelector("span").textContent=funded?T("escrowFunded"):approved?T("walletReady"):T("approvalLocked")}
function stage(transaction,label,after){pending={transaction,label,after};show("intent",{action:label,network:"Arbitrum One (42161)",...transaction});$("consent").checked=false;$("send").disabled=true;visible("review");$("review").scrollIntoView({behavior:"smooth"})}
function saveDraft(){if(draft)localStorage.setItem("agentnotary.mainnetDraft",JSON.stringify(draft))}
function clearPending(){pendingHash="";localStorage.removeItem("agentnotary.pendingTx")}
function saveUncertain(value){uncertainIntent=value;if(value)localStorage.setItem("agentnotary.uncertainIntent",JSON.stringify(value));else localStorage.removeItem("agentnotary.uncertainIntent")}
async function reconcileApproval(){if(!draft||!cfg?.escrow||!account)return;const owner=account.slice(2).padStart(64,"0"),spender=cfg.escrow.slice(2).padStart(64,"0");const raw=await provider().request({method:"eth_call",params:[{to:USDC,data:"0xdd62ed3e"+owner+spender},"latest"]});if(BigInt(raw)>=BigInt(draft.buyer_total_units)){draft.approvalConfirmed=true;saveDraft();$("propose").disabled=false;fundingProgress(true);show("status",T("approvalFound"))}}

async function prepare(){if(uncertainIntent||pendingHash)throw Error(T("checkSavedFirst"));if(!cfg?.accepting_funds)throw Error(T("notOpen"));account=await wallet();if(!validateSeller())throw Error(T("differentWallets"));const mode=$("mode").value,policy=mode==="automatic"?cfg.automatic_policy_hash:cfg.review_policy_hash;if(!validHash(policy))throw Error(T("policyMissing"));const bytes=new Uint8Array(32);crypto.getRandomValues(bytes);const salt="0x"+[...bytes].map(x=>x.toString(16).padStart(2,"0")).join("");const intent={buyer:account,seller:$("seller").value.trim(),mode,amount:$("amount").value,salt,manifest:$("manifest").value,policy_hash:policy,fallback_seller_bps:Math.round(Number($("fallback").value)*100),acceptance_window:Number($("acceptWindow").value),delivery_window:Number($("deliveryWindow").value),decision_window:Number($("decisionWindow").value),arbitration_window:Number($("arbitrationWindow").value)};draft=await api("/prepare-proposal",intent);draft._intent=intent;draft.approvalConfirmed=false;saveDraft();show("total",T("total",{amount:format(draft.buyer_total_units)}));show("costs",fundingCosts(draft));$("dealId").value=draft.deal_id;$("propose").disabled=true;fundingProgress(false);visible("funding")}
async function read(){current=await api("/deals/"+$("dealId").value.trim());reviewState=null;if(current.state==="DISPUTED")reviewState=await api(`/deals/${current.deal_id}/review-status`).catch(()=>null);visible("dealView");show("dealSummary",`${current.mode==="AUTOMATIC"?T("modeAutomatic"):T("modeReview")} · ${T("state"+current.state)} · ${format(current.amount_units)} USDC · ${I18N.t?I18N.t("buyer"):"Buyer"} ${short(current.buyer)} · ${I18N.t?I18N.t("seller"):"Seller"} ${short(current.seller)}`);if(reviewState){const appeal=reviewState.appealed?T("appealed"):T("appealUntil",{date:dateTime(new Date(Number(reviewState.appeal_deadline)*1000))});const text=reviewState.pending?T("aiProposal",{decision:reviewState.decision,confidence:(Number(reviewState.confidence_bps)/100).toFixed(1),appeal}):T("reviewExamining");show("aiReviewStatus",text);visible("aiReviewStatus")}else visible("aiReviewStatus",false);show("dealData",{...current,review:reviewState});$("dealLink").value=localizedDealLink(current.deal_id);renderActions()}
function button(label,fn,kind=""){const b=document.createElement("button");b.textContent=label;b.className=kind;b.onclick=()=>run(fn);$("actions").appendChild(b)}
function renderActions(){const box=$("actions");box.replaceChildren();if(!current)return;const now=Number(current.chain_time);if(current.state==="PROPOSED"){if(same(account,current.buyer))button(T("cancelRefund"),"cancelProposal","secondary");if(same(account,current.seller)){if(current.mode==="BUYER_REVIEW")button(T("approveBond"),"approveSellerBond");button(current.mode==="BUYER_REVIEW"?T("acceptDealStep"):T("acceptDeal"),"sellerAccept")}if(now>=Number(current.acceptance_deadline))button(T("returnExpired"),"expireProposal","secondary")}if(current.state==="LOCKED"){if(same(account,current.seller))button(T("submitDelivery"),"deliver");if(now>=Number(current.delivery_deadline))button(T("refundUndelivered"),"expireUndelivered","secondary")}if(current.state==="DELIVERED"&&current.mode==="BUYER_REVIEW"){if(same(account,current.buyer)){button(T("acceptPay"),"acceptDelivery");if(now<Number(current.decision_deadline))button(T("openDispute"),"disputeDelivery","danger")}if(now>=Number(current.decision_deadline))button(T("finalizeSilence"),"finalizeIfSilent","secondary")}if(current.state==="DELIVERED"&&current.mode==="AUTOMATIC"&&now>=Number(current.decision_deadline))button(T("validationFallback"),"finalizeUnresolvedAutomatic","secondary");if(current.state==="DISPUTED"){if(reviewState?.pending&&!reviewState.appealed&&now<Number(reviewState.appeal_deadline)&&(same(account,current.buyer)||same(account,current.seller)))button(T("appealAi"),"appealAI","danger");if(reviewState?.pending&&!reviewState.appealed&&now>=Number(reviewState.appeal_deadline))button(T("finalizeAi"),"finalizeAI");if(now>=Number(current.arbitration_deadline))button(T("arbitrationFallback"),"finalizeUnresolvedReview","secondary")}button(T("refreshDeal"),"refresh","secondary")}
async function run(action){try{if(action==="refresh")return await read();if(action==="appealAI"||action==="finalizeAI"){const d=await api(`/deals/${current.deal_id}/prepare-review-action`,{caller:await wallet(),action:action==="appealAI"?"appeal":"finalize"});return stage(d.transaction,d.action,"deal")}const reasonHash=action==="disputeDelivery"?await disputeReasonHash($("reasonHash").value):$("reasonHash").value.trim();const body={caller:await wallet(),action,content_hash:$("contentHash").value.trim(),uri:$("uri").value.trim(),reason_hash:reasonHash,evidence_uri:$("evidenceUri").value.trim(),decision:0};const d=await api(`/deals/${current.deal_id}/prepare-action`,body);stage(d.transaction,action,action==="approveSellerBond"?"bond":"deal");pending.reason_hash=reasonHash}catch(e){show("status",error(e))}}
async function receipt(hash){const p=provider();for(let i=0;i<60;i++){const r=await p.request({method:"eth_getTransactionReceipt",params:[hash]});if(r)return r;await new Promise(resolve=>setTimeout(resolve,2000))}return null}
async function send(){if(sending)return;try{sending=true;$("send").disabled=true;const p=provider(),a=await wallet();if(!pending)throw Error(T("prepareAgain"));if(!same(a,pending.transaction.from)){if(pending.after==="safe"){await navigator.clipboard.writeText(JSON.stringify(pending.transaction,null,2));show("receipt",T("safeCopied"));return}throw Error(T("walletMismatch"))}validatePreparedTransaction(pending.transaction,a);if(pendingHash||uncertainIntent)throw Error(T("checkBeforeSend"));await p.request({method:"eth_call",params:[pending.transaction,"latest"]});saveUncertain({kind:pending.after,deal_id:draft?.deal_id||current?.deal_id||"",from:a,to:pending.transaction.to});let hash;try{hash=await p.request({method:"eth_sendTransaction",params:[pending.transaction]})}catch(e){if(e.code===4001)saveUncertain(null);throw e}pendingHash=hash;localStorage.setItem("agentnotary.pendingTx",hash);saveUncertain(null);show("receipt",T("submitted",{hash}));const r=await receipt(hash);if(!r){show("receipt",T("stillPending",{hash}));return}if(BigInt(r.status)!==1n){clearPending();throw Error(T("confirmedFailed"))}show("receipt",T("confirmed",{hash}));clearPending();const completed=pending;pending=null;if(completed.after==="approval"){draft.approvalConfirmed=true;saveDraft();$("propose").disabled=false;fundingProgress(true);show("status",T("approvalConfirmed"))}else if(completed.after==="proposal"){fundingProgress(true,true);localStorage.removeItem("agentnotary.mainnetDraft");const link=localizedDealLink(draft.deal_id);$("dealLink").value=link;visible("open",true);show("status",T("fundedShare"));await navigator.clipboard.writeText(link).catch(()=>{})}else{await read().catch(()=>{});await balances().catch(()=>{})}}catch(e){show("status",error(e))}finally{sending=false;$("send").disabled=!$("consent").checked||!!pendingHash||!!uncertainIntent}}
async function checkPending(){account=await wallet();if(!pendingHash){if(!uncertainIntent)return show("receipt",T("noUnresolved"));const supplied=$("knownTxHash").value.trim();if(!validHash(supplied))return show("receipt",T("lostResponse"));pendingHash=supplied;localStorage.setItem("agentnotary.pendingTx",pendingHash)}const r=await provider().request({method:"eth_getTransactionReceipt",params:[pendingHash]});if(!r)return show("receipt",T("stillUnresolved",{hash:pendingHash}));if(uncertainIntent&&(!same(r.from,uncertainIntent.from)||!same(r.to,uncertainIntent.to)))return show("receipt",T("receiptMismatch"));const kind=uncertainIntent?.kind||(draft?.approvalConfirmed===false?"approval":"deal");const dealId=uncertainIntent?.deal_id||draft?.deal_id||"";show("receipt",BigInt(r.status)===1n?T("confirmed",{hash:pendingHash}):T("failed",{hash:pendingHash}));clearPending();saveUncertain(null);if(BigInt(r.status)===1n&&(kind==="proposal"||kind==="deal")&&validHash(dealId)){$("dealId").value=dealId;visible("open",true);await read().catch(()=>{})}if(BigInt(r.status)===1n&&kind==="approval")await reconcileApproval().catch(()=>{})}

$("connect").onclick=()=>connect().catch(e=>show("status",error(e)));$("buyerRole").onclick=()=>select("buyerRole");$("sellerRole").onclick=()=>select("sellerRole");$("prepare").onclick=()=>prepare().catch(e=>show("status",error(e)));$("approve").onclick=()=>stage(draft.approval,T("approveAction"),"approval");$("propose").onclick=()=>stage(draft.proposal,T("fundAction"),"proposal");$("read").onclick=()=>read().catch(e=>show("status",error(e)));$("copyLink").onclick=()=>navigator.clipboard.writeText($("dealLink").value);$("consent").onchange=()=>$("send").disabled=!$("consent").checked;$("send").onclick=send;$("cancel").onclick=()=>{pending=null;visible("review",false)};$("checkTx").onclick=()=>checkPending().catch(e=>show("status",error(e)));$("mode").onchange=()=>{const review=$("mode").value==="buyer_review";$("amount").value=review?"100":"10";$("fallback").value=review?"50":"0";$("decisionWindow").value=review?"172800":"86400";$("arbitrationWindow").value="604800";updateFallback()};$("amount").oninput=updateFallback;$("fallback").oninput=updateFallback;$("seller").oninput=validateSeller;
updateFallback();const requestedRole=new URLSearchParams(location.search).get("role");if(requestedRole==="buyer")select("buyerRole");if(requestedRole==="seller")select("sellerRole");refresh().catch(e=>show("status",error(e)));if(pendingHash||uncertainIntent){visible("review");show("receipt",pendingHash?T("unresolved",{hash:pendingHash}):T("lostBeforeHash"))}const saved=localStorage.getItem("agentnotary.mainnetDraft");if(saved){try{draft=JSON.parse(saved);$("dealId").value=draft.deal_id;$("propose").disabled=!draft.approvalConfirmed;fundingProgress(draft.approvalConfirmed);visible("funding")}catch{localStorage.removeItem("agentnotary.mainnetDraft")}}const match=location.pathname.match(/\/mainnet\/deal\/(0x[0-9a-fA-F]{64})/);if(match){$("dealId").value=match[1];select("sellerRole");read().catch(e=>show("status",error(e)))}if(window.ethereum){window.ethereum.on("accountsChanged",()=>{account=null;pending=null;draft=null;localStorage.removeItem("agentnotary.mainnetDraft");location.reload()});window.ethereum.on("chainChanged",()=>location.reload())}
const agreed=sessionStorage.getItem("agentnotary.agreedTerms");if(agreed){try{const value=JSON.parse(agreed);select("buyerRole");$("mode").value="buyer_review";$("seller").value=value.seller;$("amount").value=value.amount;$("manifest").value=value.manifest;$("fallback").value="50";show("status",T("negotiationLoaded"));sessionStorage.removeItem("agentnotary.agreedTerms")}catch{sessionStorage.removeItem("agentnotary.agreedTerms")}}
